'use client'

import { useEffect, useState } from 'react'
import RoleSelection, { type Role } from './role-selection'
import { Activity, Archive, ArrowLeft, ArrowRight, Bell, BriefcaseBusiness, Check, ChevronDown, ClipboardCheck, FileCheck2, FilePlus2, Gauge, LayoutDashboard, Menu, Search, ShieldCheck, TestTube2, Upload, Users, X } from 'lucide-react'
import { getAuditTrail, type WorkflowCase } from '@/lib/workflow-engine'
import { LiveRoleWorkspace } from './live-role-workspace'
import { InspectorWorkspace } from './inspector-workspace'

const storageKey = 'trustgate-neon-workflow'
const getWorkflowState = () => ({ cases: [] as WorkflowCase[] })
const getNotificationsForRole = (_role: string) => [] as Array<{ id: string; caseId: string; targetRole: string; title: string; message: string; type: string; read: boolean; createdAt: string; actionLink: string }>
const workflowAction = (caseId: string, action: string, actor: { role: string; name: string }, metadata: Record<string, unknown> = {}) => fetch(`/api/workflow/cases/${encodeURIComponent(caseId)}/${action}`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ actor, ...metadata }) }).then(async response => { if (!response.ok) throw new Error((await response.json()).error || 'Workflow action failed'); return response.json() })
const createCase = (payload: Record<string, unknown>) => fetch('/api/workflow/cases', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ ...payload, actor: { role: 'Inspector', name: String(payload.inspector || payload.inspectorName || 'Inspector') } }) }).then(async response => ({ ok: response.ok, data: await response.json() }))
const startIdentity = (caseId: string) => workflowAction(caseId, 'complete-passport', { role: 'Inspector', name: 'Inspector' })
const completePassport = (caseId: string) => workflowAction(caseId, 'complete-passport', { role: 'Inspector', name: 'Inspector' })
const completeTestSetup = (caseId: string) => workflowAction(caseId, 'complete-test-setup', { role: 'Inspector', name: 'Inspector' })
const markEvidenceVerified = (caseId: string) => workflowAction(caseId, 'capture-evidence', { role: 'Inspector', name: 'Inspector' })
const runTrustGate = (caseId: string) => workflowAction(caseId, 'run-trustgate', { role: 'Inspector', name: 'Inspector' })
const submitToLab = (caseId: string) => workflowAction(caseId, 'submit-to-lab', { role: 'Inspector', name: 'Inspector' })
const approveCase = (caseId: string, remarks = '') => workflowAction(caseId, 'approve', { role: 'Officer', name: 'Officer' }, { remarks })
const requestOfficerRetest = (caseId: string, remarks = '') => workflowAction(caseId, 'request-retest', { role: 'Officer', name: 'Officer' }, { remarks })
const closeCase = (caseId: string) => workflowAction(caseId, 'close', { role: 'Officer', name: 'Officer' })
const markPotentialNonCompliance = (caseId: string, remarks = '') => workflowAction(caseId, 'mark-potential-non-compliance', { role: 'Officer', name: 'Officer' }, { remarks })
const generateReport = (caseId: string) => workflowAction(caseId, 'generate-report', { role: 'Officer', name: 'Officer' })
const resetWorkflowData = () => fetch('/api/workflow/reset-demo-data', { method: 'POST' })


type Step = 'Dashboard' | 'Create Case' | 'Inspection Cases' | 'Case Workflow' | 'Reports' | 'Audit Trail' | 'NAWI Passport' | 'Test Setup' | 'OIML Applicability' | 'Guided Tests' | 'Evidence Capture' | 'Calculation Engine' | 'TrustGate Review' | 'Counter-Evidence Check' | 'Officer Dashboard' | 'Verification Queue' | 'Test Setup Review' | 'Reading Review' | 'Evidence Review' | 'Case Detail' | 'User Management' | 'Role Management' | 'Rule Versions' | 'Evidence Thresholds' | 'System Settings' | 'All Cases'
type CaseData = { caseId:string; inspector:string; district:string; location:string; instrument:string; date:string; purpose:string; officer:string; priority:string; mode:string; remarks:string; manufacturer:string; model:string; serial:string; accuracy:string; maxCapacity:string; minCapacity:string; interval:string; rangeType:string; tare:string; useCase:string; lab:string; setupDate:string; temperature:string; humidity:string; masses:string; testLocation:string; setupNotes:string; status:string }
const newCaseId=()=>`TG-${new Date().toISOString().replace(/[-:TZ.]/g,'').slice(0,14)}`
const emptyCase:CaseData = { caseId:newCaseId(), inspector:'', district:'', location:'', instrument:'', date:'', purpose:'', officer:'', priority:'Normal', mode:'Field', remarks:'', manufacturer:'A&D Weighing', model:'SJ-2000HS', serial:'AD-88421', accuracy:'III', maxCapacity:'100 kg', minCapacity:'20 g', interval:'50 g', rangeType:'Single interval', tare:'Yes', useCase:'Retail trade', lab:'Legal Metrology Lab, Bhubaneswar', setupDate:'2026-09-26', temperature:'24 °C', humidity:'48%', masses:'20 kg, 50 kg, 100 kg', testLocation:'Bhubaneswar Central Market', setupNotes:'Reference masses verified before testing.', status:'Draft' }
type OfficerAction = 'Approve Report'|'Send Back to Inspector'|'Request Retest'|'Mark Potential Non-Compliance'|'Close Case'
type OfficerCase = {id:string;instrument:string;district:string;location:string;inspector:string;status:string;evidence:string;calculation:string;priority:string;trustgate:string;updated:string;result:string;history:{action:string;actor:string;time:string;note:string}[]}
const workflowToOfficerCase=(item:WorkflowCase):OfficerCase=>({id:item.id,instrument:item.instrument,district:item.location,location:item.location,inspector:item.inspector,status:item.status,evidence:item.evidenceComplete?'Complete':'Incomplete',calculation:item.evidenceComplete?'Ready':'Pending',priority:item.trustgateReady<70?'Urgent':'Normal',trustgate:item.trustgateResult,updated:new Date(item.updatedAt).toLocaleString('en-IN'),result:item.remarks,history:getAuditTrail([], item.id).map(event=>({action:event.action,actor:event.actorName,time:new Date(event.timestamp).toLocaleString('en-IN'),note:event.remarks||''}))})
const VALID_ROLES: Role[] = ['Inspector', 'Lab Verifier', 'Officer', 'Admin']
const isValidRole = (value: unknown): value is Role => typeof value === 'string' && VALID_ROLES.includes(value as Role)
const navGroups = [{label:'Workspace',items:[['Dashboard',LayoutDashboard],['Create Case',FilePlus2],['Inspection Cases',BriefcaseBusiness]]},{label:'Inspection',items:[['NAWI Passport',Archive],['Guided Tests',TestTube2],['TrustGate Review',ShieldCheck]]},{label:'Decisions',items:[['Officer Dashboard',Users],['Reports',FileCheck2],['Audit Trail',Activity]]}]
type PermissionKey = 'canCreateCase'|'canUploadEvidence'|'canReviewSetup'|'canReviewEvidence'|'canRecommendRetest'|'canApproveReport'|'canGenerateReport'|'canMarkNonCompliance'|'canManageUsers'|'canManageRules'|'canConfigureSystem'|'canViewAuditTrail'|'canResetDemoData'
const permissions:Record<Role,Record<PermissionKey,boolean>>={Inspector:{canCreateCase:true,canUploadEvidence:true,canReviewSetup:false,canReviewEvidence:false,canRecommendRetest:false,canApproveReport:false,canGenerateReport:false,canMarkNonCompliance:false,canManageUsers:false,canManageRules:false,canConfigureSystem:false,canViewAuditTrail:true,canResetDemoData:true},'Lab Verifier':{canCreateCase:false,canUploadEvidence:false,canReviewSetup:true,canReviewEvidence:true,canRecommendRetest:true,canApproveReport:false,canGenerateReport:false,canMarkNonCompliance:false,canManageUsers:false,canManageRules:false,canConfigureSystem:false,canViewAuditTrail:true,canResetDemoData:true},Officer:{canCreateCase:false,canUploadEvidence:false,canReviewSetup:false,canReviewEvidence:false,canRecommendRetest:false,canApproveReport:true,canGenerateReport:true,canMarkNonCompliance:true,canManageUsers:false,canManageRules:false,canConfigureSystem:false,canViewAuditTrail:true,canResetDemoData:true},Admin:{canCreateCase:false,canUploadEvidence:false,canReviewSetup:false,canReviewEvidence:false,canRecommendRetest:false,canApproveReport:false,canGenerateReport:false,canMarkNonCompliance:false,canManageUsers:true,canManageRules:true,canConfigureSystem:true,canViewAuditTrail:true,canResetDemoData:true}}
const permissionNotice=(role:Role,action:string)=>`Your ${role} role cannot ${action}. Use the role selector in the top-right to continue.`
const canAccessStep=(_role:Role,step:Step)=>['Dashboard','Create Case','Inspection Cases','Case Workflow','Reports','Audit Trail'].includes(step)
const roleNavGroups=(_role:string)=>[{label:'Workspace',items:[['Dashboard',LayoutDashboard],['Create Case',FilePlus2],['Inspection Cases',BriefcaseBusiness],['Case Workflow',ClipboardCheck],['Reports',FileCheck2],['Audit Trail',Activity]]}]
const tests = [{name:'Repeatability',status:'Applicable',tone:'green',reason:'Required for all NAWI instruments.',evidence:'Scale display photos at repeated load point.'},{name:'Eccentricity',status:'Applicable',tone:'green',reason:'A load receptor is present.',evidence:'Load point photo and indication.'},{name:'Indication Error',status:'Applicable',tone:'green',reason:'Required for performance verification.',evidence:'Reading table and calibrated masses.'},{name:'Tare',status:'Applicable',tone:'green',reason:'Passport records tare support = Yes.',evidence:'Zero and tare display photos.'},{name:'Creep',status:'Needs Review',tone:'orange',reason:'Confirm instrument type and 30-minute hold.',evidence:'Start/end indication with timestamp.'},{name:'Substitution',status:'Not Applicable',tone:'purple',reason:'Current capacity does not require substitution.',evidence:'Mass certificate and setup record.'}]
function StatusBadge({children,tone='blue'}:{children:React.ReactNode;tone?:string}){return <span className={`status-badge status-${tone}`}><span className="status-dot"/>{children}</span>}
function Field({label,value,onChange,type='text',options,required=false}:{label:string;value:string;onChange:(v:string)=>void;type?:string;options?:string[];required?:boolean}){return <label className="form-field"><span>{label}{required&&<b> *</b>}</span>{options?<select value={value} onChange={e=>onChange(e.target.value)}>{options.map(o=><option key={o}>{o}</option>)}</select>:type==='textarea'?<textarea rows={3} value={value} onChange={e=>onChange(e.target.value)}/>:<input type={type} value={value} onChange={e=>onChange(e.target.value)}/>}</label>}

function Validation({message}:{message?:string}){return message?<div className="validation" role="alert">{message}</div>:null}
function UploadBox({label,required=false,status='Missing',onAction}:{label:string;required?:boolean;status?:string;onAction?:()=>void}){return <div className="upload-box"><div className="upload-box-top"><Upload size={17}/><StatusBadge tone={status==='Verified'?'green':status==='Needs Retake'?'red':required?'orange':'purple'}>{required?'Required':'Optional'}</StatusBadge></div><strong>{label}</strong><span>{status==='Missing'?'Evidence not yet linked to a test step':status==='Needs Retake'?'Quality gate failed — retake required':'Evidence verified and audit-linked'}</span><small className="evidence-meta">{status==='Verified'?'Quality 96% · captured 29 Sep 2026':'Linked test step · awaiting upload'}</small><button type="button" className="secondary-button" onClick={onAction}>{status==='Missing'?'Upload Evidence':status==='Needs Retake'?'Request Retake':'View Evidence'}</button></div>}

export function TrustGateDashboard({ initialCaseId, initialStep }: { initialCaseId?: string; initialStep?: Step } = {}){
 const [active,setActive]=useState<Step>(initialStep || 'Dashboard'); const [mobileOpen,setMobileOpen]=useState(false); const [role,setRole]=useState(''); const [roleSelected,setRoleSelected]=useState(false); const [caseData,setCaseData]=useState<CaseData>(emptyCase); const [errors,setErrors]=useState<string[]>([]); const [selectedTest,setSelectedTest]=useState('Repeatability'); const [readingSaved,setReadingSaved]=useState(false); const [reading,setReading]=useState({load:'50 kg',initial:'0.00',increment:'50',observed:'50.02',unit:'kg',note:''});
 const [evidenceComplete,setEvidenceComplete]=useState(false); const [calculationRun,setCalculationRun]=useState(false); const [trustgateRun,setTrustgateRun]=useState(false); const [reportGenerated,setReportGenerated]=useState(false); const [saveMessage,setSaveMessage]=useState(''); const [workflowCases,setWorkflowCases]=useState<ReturnType<typeof getWorkflowState>['cases']>([]); const [notifications,setNotifications]=useState<ReturnType<typeof getNotificationsForRole>>([]); const [notificationOpen,setNotificationOpen]=useState(false); const [accessNotice,setAccessNotice]=useState(''); const [auditTrail,setAuditTrail]=useState<string[]>([]); const [auditFilter,setAuditFilter]=useState('All events'); const [counterRecommendation,setCounterRecommendation]=useState('Send for manual review'); const [officerCases,setOfficerCases]=useState<OfficerCase[]>([]); const [selectedOfficerCase,setSelectedOfficerCase]=useState<OfficerCase|null>(null); const [decisionModal,setDecisionModal]=useState<{action:OfficerAction;caseItem:OfficerCase}|null>(null); const [hydrated,setHydrated]=useState(false)
 useEffect(()=>{const savedRole=localStorage.getItem('trustgate-selected-role');if(isValidRole(savedRole)){setRole(savedRole);setRoleSelected(true)}setHydrated(true)},[])
 useEffect(()=>{if(!hydrated||!isValidRole(role))return;let cancelled=false;const sync=async()=>{try{const response=await fetch('/api/workflow/cases',{cache:'no-store'});if(!response.ok)throw new Error('Unable to load cases');const cases=await response.json();if(cancelled)return;setWorkflowCases(cases);setNotifications(cases.filter((item:WorkflowCase)=>item.ownerRole===role).map((item:WorkflowCase)=>({id:item.id,caseId:item.id,targetRole:role,title:`${item.id} requires your action`,message:`${item.status.replaceAll('_',' ')} · ${item.instrument}`,type:'info',read:false,createdAt:item.updatedAt,actionLink:`/cases/${item.id}`})));setOfficerCases(cases.filter((item:WorkflowCase)=>role==='Admin'||item.ownerRole===role).map(workflowToOfficerCase))}catch{if(!cancelled)setAccessNotice('Neon workflow data could not be loaded.')} };sync();return()=>{cancelled=true}},[hydrated,role,active])
 useEffect(()=>{if(!hydrated)return;const params=new URLSearchParams(window.location.search);const view=params.get('view');const caseId=initialCaseId||params.get('caseId');if(initialStep)setActive(initialStep);if(view==='audit'&&isValidRole(role)&&canAccessStep(role,'Audit Trail'))setActive('Audit Trail');if((view==='officer'||initialCaseId)&&isValidRole(role)&&canAccessStep(role,'Officer Dashboard')){setActive(initialCaseId?'Case Detail':'Officer Dashboard');const item=officerCases.find(c=>c.id===caseId);if(item)setSelectedOfficerCase(item)}},[hydrated,officerCases,initialCaseId,initialStep,role])
 const selectRole=(nextRole:Role)=>{setRole(nextRole);setRoleSelected(true);localStorage.setItem('trustgate-selected-role',nextRole);setActive('Dashboard')}; const switchRole=()=>{localStorage.removeItem('trustgate-selected-role');setRoleSelected(false);setRole('');setActive('Dashboard')}; const resetDemo=()=>{resetWorkflowData();localStorage.removeItem(storageKey);setActive('Dashboard');setRole(isValidRole(role)?role:'Inspector');setRoleSelected(true);setCaseData(emptyCase);setSelectedTest('Repeatability');setReadingSaved(false);setReading({load:'50 kg',initial:'0.00',increment:'50',observed:'50.02',unit:'kg',note:''});setEvidenceComplete(false);setCalculationRun(false);setTrustgateRun(false);setReportGenerated(false);setAuditTrail([]);setAuditFilter('All events');setCounterRecommendation('Send for manual review');setOfficerCases([]);setSelectedOfficerCase(null);setErrors([])}
 const update=(name:keyof CaseData,value:string)=>setCaseData(c=>({...c,[name]:value})); if(hydrated&&!roleSelected)return <RoleSelection onSelect={selectRole}/>; if(hydrated&&role==='Inspector')return <InspectorWorkspace/>; const go=(next:Step)=>{if(!isValidRole(role)||!canAccessStep(role,next)){setAccessNotice(permissionNotice(isValidRole(role)?role:'Inspector',next==='Reports'?'generate reports':`open ${next.toLowerCase()}`));setMobileOpen(false);return}setAccessNotice('');setActive(next);setMobileOpen(false);window.scrollTo({top:0,behavior:'smooth'})}; const validate=(fields:(keyof CaseData)[])=>{const missing=fields.filter(f=>!caseData[f]);setErrors(missing);return !missing.length};
 const workflowCaseId=caseData.caseId.trim() || newCaseId(); const openCaseWorkflow=()=>{const selected=workflowCases[0];if(selected)window.location.href=`/cases/${encodeURIComponent(selected.id)}`;else setAccessNotice('No Neon inspection case is available. Create a case first.')}; const saveDraft=async()=>{if(!caseData.caseId) setCaseData(current=>({...current,caseId:newCaseId()})); if(!validate(['inspector','district','location','instrument','date','purpose','officer']))return false; setSaveMessage(''); const response=await createCase({id:workflowCaseId,caseId:workflowCaseId,inspector:caseData.inspector,inspectorName:caseData.inspector,district:caseData.district,location:caseData.location,inspectionLocation:caseData.location,instrument:caseData.instrument,instrumentType:caseData.instrument,inspectionDate:caseData.date,purpose:caseData.purpose,assignedOfficer:caseData.officer,officerName:caseData.officer,priority:caseData.priority,inspectionMode:caseData.mode,remarks:caseData.remarks}); if(!response.ok){setSaveMessage('Unable to save draft. Please try again.');return false} const saved=response.data; setWorkflowCases(current=>[saved,...current.filter(item=>item.id!==saved.id)]); setSaveMessage('Draft saved successfully'); return true}; const continueCase=async()=>{if(!validate(['inspector','district','location','instrument','date','purpose','officer']))return false; const saved=await saveDraft(); if(!saved)return false; await completePassport(workflowCaseId); window.location.href=`/cases/${encodeURIComponent(workflowCaseId)}`; return true}; const continuePassport=()=>{if(!validate(['manufacturer','model','serial','maxCapacity','minCapacity','interval','useCase']))return false; completeTestSetup(workflowCaseId); go('Test Setup'); return true}; const continueSetup=()=>{if(!validate(['lab','setupDate','temperature','humidity','masses','testLocation']))return false; go('OIML Applicability'); return true};
 const pageTitle=active==='Dashboard'?(role==='Officer'?'Officer dashboard':role==='Admin'?'Administration':role==='Lab Verifier'?'Verification workspace':'Good morning.'):active==='Inspection Cases'?'Inspection cases':active==='Officer Dashboard'?(selectedOfficerCase?'Case detail · '+selectedOfficerCase.id:'Officer dashboard'):active==='Reports'?'Reports':active==='Audit Trail'?'Audit trail':active; const stepIndex=active==='Create Case'?0:active==='NAWI Passport'?1:active==='Test Setup'?2:active==='OIML Applicability'?3:active==='Guided Tests'?4:active==='Evidence Capture'?5:active==='Calculation Engine'?6:active==='TrustGate Review'?7:active==='Counter-Evidence Check'?7:5; const field=(name:keyof CaseData,label:string,type='text',options?:string[],required=false)=><Field label={label} value={caseData[name]} onChange={v=>update(name,v)} type={type} options={options} required={required}/>;
 return <div className="app-shell"><aside className={`sidebar ${mobileOpen?'sidebar-open':''}`}><div className="brand-row"><div className="brand-mark"><Gauge size={20}/></div><div><div className="brand-name">PramaanSetu</div><div className="brand-subtitle">NAWI Reporting Portal</div></div><button className="icon-button mobile-close" aria-label="Close navigation" onClick={()=>setMobileOpen(false)}><X size={19}/></button></div><div className="department-chip"><div className="ashoka-mark"><ShieldCheck size={14}/></div><div><strong>Legal Metrology</strong><span>Department of Consumer Affairs</span></div></div><nav className="nav-area" aria-label="Primary navigation">{roleNavGroups(role).map(g=><div className="nav-group" key={g.label}><div className="nav-label">{g.label}</div>{g.items.map(([label,Icon])=><button key={label as string} className={`nav-item ${active===label?'nav-active':''}`} onClick={()=>{if(label==='Case Workflow'){openCaseWorkflow();setMobileOpen(false)}else if(label==='Inspection Cases')go('Inspection Cases');else if(label==='Officer Dashboard'){setSelectedOfficerCase(null);go('Officer Dashboard' as Step)}else if(label==='Reports')go('Reports');else if(label==='Audit Trail')go('Audit Trail');else if(label==='Create Case')go('Create Case');else if(label==='Verification Queue'||label==='All Cases')go(label as Step);else if(label==='Test Setup Review'||label==='Reading Review'||label==='Evidence Review')go(label as Step);else if(label==='Test Setup'||label==='OIML Applicability'||label==='Evidence Capture'||label==='Calculation Engine')go(label as Step);else if(label==='Calculation Engine')go('Calculation Engine');else if(label==='Case Detail')go('Case Detail');else if(label==='Counter-Evidence Check')go('Counter-Evidence Check');else if(label==='User Management'||label==='Role Management'||label==='Rule Versions'||label==='Evidence Thresholds'||label==='System Settings')go(label as Step);else go('Dashboard')}}><Icon size={17}/><span>{label as string}</span>{label==='TrustGate Review'&&<span className="nav-count">4</span>}</button>)}</div>)}</nav><div className="sidebar-bottom"><div className="sidebar-footer"><span className="online-dot"/>System operational<span className="version">v2.4.1</span></div></div></aside>
 <main className="main-content"><header className="topbar"><button className="icon-button mobile-menu" aria-label="Open navigation" onClick={()=>setMobileOpen(true)}><Menu size={21}/></button><div className="breadcrumbs"><span>Workspace</span><span>/</span><strong>{active}</strong></div><div className="topbar-actions"><button className="icon-button" aria-label="Search unavailable" title="Global search is not configured" disabled><Search size={18}/></button><div className="notification-wrap"><button className="icon-button notification-button" aria-label="Notifications" aria-expanded={notificationOpen} onClick={()=>setNotificationOpen(open=>!open)}><Bell size={18}/>{notifications.some(item=>!item.read)&&<i/>}</button>{notificationOpen&&<div className="notification-popover" role="dialog" aria-label="Notifications"><div className="panel-heading"><strong>Notifications</strong><span>{notifications.filter(item=>!item.read).length} unread</span></div>{notifications.length?notifications.slice(0,5).map(item=><button className={`notification-item ${item.read?'read':''}`} key={item.id} onClick={()=>{setNotificationOpen(false);window.location.href=item.actionLink}}><strong>{item.title}</strong><span>{item.message}</span><small>{new Date(item.createdAt).toLocaleString('en-IN')}</small></button>):<p className="empty-state">No role-specific notifications.</p>}</div>}</div><div className="role-select"><span className="avatar">AS</span><select aria-label="Select role" value={role} onChange={e=>e.target.value==='Switch Role'?switchRole():selectRole(e.target.value as Role)}><option>Inspector</option><option>Lab Verifier</option><option>Officer</option><option>Admin</option><option disabled>──────────</option><option>Switch Role</option></select><ChevronDown size={14}/></div></div></header><div className="page-wrap"><section className="welcome-row"><div><p className="eyebrow">{new Date().toLocaleDateString('en-IN',{weekday:'long',day:'2-digit',month:'long',year:'numeric'}).toUpperCase()}</p><h1>{pageTitle}</h1><p className="page-intro">{active==='Dashboard'?"Here's the current state of your inspection work.":'Official NAWI inspection workflow and traceability record.'}</p></div>{active==='Dashboard'&&<button className="primary-button" onClick={()=>go('Create Case')}><FilePlus2 size={17}/> Create inspection case</button>}</section>
 {accessNotice&&<div className="validation" role="alert">{accessNotice}</div>}{active!=='Dashboard'&&active!=='Inspection Cases'&&<><section className="principle-banner"><div className="principle-icon"><ShieldCheck size={20}/></div><div><strong>Evidence Before Result</strong><p>No result is generated until required readings, evidence, quality checks and officer review are complete.</p></div><span className="banner-tag">R 76 workflow</span></section></>}
 {active==='Audit Trail'&&<AuditTrail filter={auditFilter} setFilter={setAuditFilter} caseId={new URLSearchParams(typeof window!=='undefined'?window.location.search:'').get('caseId')||undefined}/>} {active==='Dashboard'&&(role==='Lab Verifier'||role==='Officer'||role==='Admin'?<LiveRoleWorkspace role={role} cases={workflowCases} onOpen={caseId=>window.location.href=`/cases/${encodeURIComponent(caseId)}`} onAction={async (caseId,action)=>{try{await workflowAction(caseId,action,{role,name:role});const response=await fetch('/api/workflow/cases',{cache:'no-store'});if(response.ok)setWorkflowCases(await response.json())}catch(error){setAccessNotice(error instanceof Error?error.message:'Workflow action failed')}}}/>:<Dashboard role={role} cases={workflowCases} onCreate={()=>go('Create Case')} onCases={()=>go('Inspection Cases')} onTrustGate={openCaseWorkflow}/>)} {active==='Inspection Cases'&&<CaseList cases={workflowCases} onCreate={()=>go('Create Case')} onView={(caseId)=>{window.location.href=`/cases/${encodeURIComponent(caseId)}`}}/>} {active==='Create Case'&&<CaseForm field={field} errors={errors} saveMessage={saveMessage} onSave={saveDraft} onContinue={continueCase} />}{active==='NAWI Passport'&&<Passport field={field} errors={errors} onContinue={continuePassport} onBack={()=>go('Create Case')} caseData={caseData} />}{active==='Test Setup'&&<Setup field={field} errors={errors} onContinue={continueSetup} onBack={()=>go('NAWI Passport')}/>} {active==='OIML Applicability'&&<Applicability caseData={caseData} onStart={t=>{setSelectedTest(t);go('Guided Tests')}} onContinue={()=>{update('status','OIML Tests Selected');go('Guided Tests')}} onBack={()=>go('Test Setup')}/>}{active==='Guided Tests'&&<Guided selectedTest={selectedTest} setSelectedTest={setSelectedTest} reading={reading} setReading={setReading} saved={readingSaved} onSave={()=>{setReadingSaved(true);update('status','Evidence Captured')}} onEvidence={()=>go('Evidence Capture')} onBack={()=>go('OIML Applicability')}/>} {active==='Evidence Capture'&&<Evidence complete={evidenceComplete} onComplete={()=>{markEvidenceVerified(workflowCaseId);setEvidenceComplete(true);update('status','Ready for Calculation')}} onBack={()=>go('Guided Tests')} />} {active==='Calculation Engine'&&<CalculationEngine caseData={caseData} run={calculationRun} onRun={()=>{setCalculationRun(true);update('status','Ready for TrustGate Review')}} onContinue={()=>go('TrustGate Review')} />} {active==='TrustGate Review'&&<TrustGateReview evidenceComplete={evidenceComplete} calculationRun={calculationRun} trustgateRun={trustgateRun} onRun={()=>{runTrustGate(workflowCaseId);setTrustgateRun(true);update('status',evidenceComplete?'Ready for Officer Review':'Evidence Pending')}} onBack={()=>go('Evidence Capture')} onRetest={()=>{update('status','Needs Retest');go('Guided Tests')}} onContinue={()=>go('Counter-Evidence Check')} onSubmit={()=>{submitToLab(workflowCaseId);setTrustgateRun(true);setActive('Dashboard')}} />} {active==='Counter-Evidence Check'&&<CounterEvidence recommendation={counterRecommendation} setRecommendation={setCounterRecommendation} onContinue={()=>{update('status','Ready for Officer Review');go('Inspection Cases')}} />}
 <footer className="app-footer"><span>PramaanSetu · NAWI Reporting</span><span>Evidence Before Result — every finding must be verified, traceable and officer-approved.</span><span>Legal Metrology Inspection System</span></footer></div></main></div>
}
function SettingsPage({role,onSwitch,onReset}:{role:string;onSwitch:()=>void;onReset:()=>void}){return <section className="settings-grid"><div className="settings-reset"><span>Current role: <strong>{role}</strong></span><button type="button" className="secondary-button" onClick={onSwitch}>Switch Role</button></div><div className="settings-reset"><span>Data source: Neon PostgreSQL · Environment: Production · Version 2.4.1</span>{role==='Admin'&&<button type="button" className="secondary-button" onClick={onReset}>Reset seed data</button>}</div><article className="panel settings-card"><div className="panel-heading"><div><p className="eyebrow">ACCESS CONTROL</p><h2>User roles</h2></div><StatusBadge tone="green">Configured</StatusBadge></div><div className="settings-list"><div><strong>Inspector</strong><span>Case intake, passport, tests and evidence capture</span></div><div><strong>Lab verifier</strong><span>Traceability checks and calculation verification</span></div><div><strong>Legal Metrology officer</strong><span>TrustGate decisions, approval and report release</span></div></div></article><article className="panel settings-card"><div className="panel-heading"><div><p className="eyebrow">RULE GOVERNANCE</p><h2>Rule versions</h2></div><StatusBadge tone="blue">OIML R 76-2</StatusBadge></div><div className="settings-list"><div><strong>Applicability rules</strong><span>OIML R 76-1 / R 76-2 · version 2026.1</span></div><div><strong>MPE thresholds</strong><span>Accuracy class III · verified by officer</span></div><div><strong>Evidence quality threshold</strong><span>Minimum confidence 85% · manual review below threshold</span></div></div></article><article className="panel settings-card"><div className="panel-heading"><div><p className="eyebrow">SYSTEM CONFIGURATION</p><h2>Evidence quality thresholds</h2></div><StatusBadge tone="orange">Review recommended</StatusBadge></div><div className="settings-list"><div><strong>Image clarity</strong><span>Blur, glare and frame coverage checks enabled</span></div><div><strong>Officer approval</strong><span>Required before R 76-2 report generation</span></div><div><strong>Audit retention</strong><span>Immutable activity trail · prototype policy: 7 years</span></div></div></article></section>}

function CaseForm({field,errors,saveMessage,onSave,onContinue}:{field:any;errors:string[];saveMessage:string;onSave:()=>void;onContinue:()=>void}){return <section className="workflow-card"><div className="card-heading"><div><p className="eyebrow">STEP 1 OF 8 · CASE INTAKE</p><h2>Create inspection case</h2></div><StatusBadge tone="orange">Draft</StatusBadge></div><div className="form-grid">{field('caseId','Case ID')}{field('inspector','Inspector name','text',undefined,true)}{field('district','District','text',undefined,true)}{field('location','Inspection location','text',undefined,true)}{field('instrument','Instrument type','text',undefined,true)}{field('date','Inspection date','date',undefined,true)}{field('purpose','Purpose of inspection','text',undefined,true)}{field('officer','Assigned officer','text',undefined,true)}{field('priority','Priority','text',['Normal','Urgent'])}{field('mode','Inspection mode','text',['Field','Lab'])}<div className="form-span">{field('remarks','Remarks','textarea')}</div></div>{errors.length?<Validation message="Please complete all required case intake fields."/>:saveMessage&&<div className={saveMessage.startsWith('Unable')?'validation':'success-message'} role="status">{saveMessage}</div>}<div className="form-actions"><button type="button" className="secondary-button" onClick={onSave}>Save Draft</button><button type="button" className="primary-button" onClick={onContinue}>Continue to Case Workflow <ArrowRight size={16}/></button></div></section>}
function Passport({field,errors,onContinue,onBack,caseData}:{field:any;errors:string[];onContinue:()=>void;onBack:()=>void;caseData:CaseData}){return <section className="workflow-card"><div className="card-heading"><div><p className="eyebrow">STEP 2 OF 8 · VERIFIED IDENTITY</p><h2>NAWI Digital Passport</h2></div><StatusBadge tone="blue">Identity Verified</StatusBadge></div><div className="form-grid">{field('manufacturer','Manufacturer','text',undefined,true)}{field('model','Model','text',undefined,true)}{field('serial','Serial number','text',undefined,true)}{field('accuracy','Accuracy class','text',['I','II','III','IIII'])}{field('maxCapacity','Max capacity','text',undefined,true)}{field('minCapacity','Min capacity','text',undefined,true)}{field('interval','Verification scale interval e','text',undefined,true)}{field('rangeType','Range type','text',['Single interval','Multi interval','Multi range'])}{field('tare','Tare support','text',['Yes','No'])}{field('useCase','Instrument use case','text',undefined,true)}<div className="form-span upload-grid"><UploadBox label="Nameplate photo" required status="Verified"/><UploadBox label="Identity document" status="Verified"/></div></div><div className="qr-card"><div className="qr-placeholder">QR</div><div><p className="eyebrow">QR-LINKED PROFILE</p><strong>{caseData.caseId}</strong><p>{caseData.manufacturer||'Manufacturer'} · {caseData.model||'Model'} · {caseData.serial||'Serial pending'}</p></div><StatusBadge tone="green">Verified profile</StatusBadge></div><Validation message={errors.length?'Please complete all required passport fields.':undefined}/><div className="form-actions"><button className="secondary-button" onClick={()=>history.back()}><ArrowLeft size={16}/> Back</button><button className="primary-button" onClick={onContinue}>Continue to Test Setup <ArrowRight size={16}/></button></div></section>}
function Setup({field,errors,onContinue,onBack}:{field:any;errors:string[];onContinue:()=>void;onBack:()=>void}){return <section className="workflow-card"><div className="card-heading"><div><p className="eyebrow">STEP 3 OF 8 · TRACEABILITY</p><h2>Test setup &amp; traceability</h2></div><StatusBadge tone="green">Ready for OIML Test Selection</StatusBadge></div><div className="form-grid">{field('lab','Officer / Lab name','text',undefined,true)}{field('setupDate','Date and time','datetime-local',undefined,true)}{field('temperature','Temperature','text',undefined,true)}{field('humidity','Humidity','text',undefined,true)}{field('masses','Calibrated test masses used','text',undefined,true)}{field('testLocation','Test location','text',undefined,true)}<div className="form-span"><UploadBox label="Calibration certificate" required status="Verified"/></div><div className="form-span">{field('setupNotes','Setup notes','textarea')}</div></div><Validation message={errors.length?'Please complete all required setup fields.':undefined}/><div className="form-actions"><button className="secondary-button" onClick={onBack}><ArrowLeft size={16}/> Back</button><button className="primary-button" onClick={onContinue}>Continue to OIML Applicability <ArrowRight size={16}/></button></div></section>}
function Applicability({caseData,onStart,onContinue,onBack}:{caseData:CaseData;onStart:(t:string)=>void;onContinue:()=>void;onBack:()=>void}){return <section className="workflow-card wide-card"><div className="card-heading"><div><p className="eyebrow">STEP 4 OF 8 · RULE-BASED SELECTION</p><h2>OIML R 76 applicability engine</h2><p className="section-note">Applicable tests are selected from the NAWI Digital Passport and recorded for officer traceability.</p></div><StatusBadge tone="green">Tests generated</StatusBadge></div><div className="instrument-summary"><SummaryItem label="Case ID" value={caseData.caseId}/><SummaryItem label="Instrument type" value={caseData.instrument||'Retail weighing scale'}/><SummaryItem label="Accuracy class" value={caseData.accuracy}/><SummaryItem label="Max capacity" value={caseData.maxCapacity||'Not entered'}/><SummaryItem label="Min capacity" value={caseData.minCapacity||'Not entered'}/><SummaryItem label="Verification scale interval e" value={caseData.interval||'Not entered'}/><SummaryItem label="Range type" value={caseData.rangeType}/><SummaryItem label="Tare support" value={caseData.tare}/></div><div className="table-wrap applicability-table"><table><thead><tr><th>Test</th><th>Applicability</th><th>Reason</th><th>Required evidence</th><th>Action</th></tr></thead><tbody>{tests.map(t=><tr key={t.name}><td className="instrument-cell">{t.name}</td><td><StatusBadge tone={t.tone}>{t.status}</StatusBadge></td><td>{t.reason}</td><td>{t.evidence}</td><td>{t.status!=='Not Applicable'?<button className="text-button" onClick={()=>onStart(t.name)}>Start Test <ArrowRight size={14}/></button>:<span className="muted">No action</span>}</td></tr>)}</tbody></table></div><div className="form-actions"><button className="secondary-button" onClick={onBack}><ArrowLeft size={16}/> Back to Test Setup</button><button className="primary-button" onClick={onContinue}>Continue to Guided Test Execution <ArrowRight size={16}/></button></div></section>}
function SummaryItem({label,value}:{label:string;value:string}){return <div><span>{label}</span><strong>{value}</strong></div>}
function Guided({selectedTest,setSelectedTest,reading,setReading,saved,onSave,onEvidence,onBack}:{selectedTest:string;setSelectedTest:(v:string)=>void;reading:any;setReading:(v:any)=>void;saved:boolean;onSave:()=>void;onEvidence:()=>void;onBack:()=>void}){return <section className="workflow-card wide-card"><div className="card-heading"><div><p className="eyebrow">STEP 5 OF 8 · FIELD OBSERVATION</p><h2>Guided test execution</h2></div><StatusBadge tone={saved?'green':'orange'}>{saved?'Evidence Captured':'Observation in progress'}</StatusBadge></div><div className="test-stepper"><span className="active">1 Select Test</span><span className="active">2 Enter Load Point</span><span>3 Capture Indication</span><span>4 Upload Evidence</span><span>5 Save Observation</span></div><div className="guided-grid"><div className="instruction-panel"><p className="eyebrow">SELECTED TEST</p><h3>{selectedTest}</h3><p>Confirm the instrument returns consistent indications under repeated application of the same load.</p><div className="info-callout"><strong>Safety / evidence reminder</strong><span>Keep the load stable, capture the display and record the exact observation before moving the load.</span></div><label className="form-field"><span>Test name</span><select value={selectedTest} onChange={e=>setSelectedTest(e.target.value)}>{tests.filter(t=>t.status!=='Not Applicable').map(t=><option key={t.name}>{t.name}</option>)}</select></label></div><div className="reading-entry"><p className="eyebrow">READING ENTRY</p><h3>Capture observation</h3><div className="form-grid compact">{[['load','Load point'],['initial','Initial indication I'],['increment','Load increment ΔL'],['observed','Observed reading']].map(([k,l])=><label className="form-field" key={k}><span>{l}</span><input value={reading[k]} onChange={e=>setReading({...reading,[k]:e.target.value})}/></label>)}<label className="form-field"><span>Unit</span><select value={reading.unit} onChange={e=>setReading({...reading,unit:e.target.value})}><option>kg</option><option>g</option><option>t</option></select></label><div className="form-span"><label className="form-field"><span>Operator note</span><textarea rows={2} value={reading.note} onChange={e=>setReading({...reading,note:e.target.value})}/></label></div></div>{!saved&&<Validation message="Reading is ready to save. Required evidence must be linked before completion."/>}<div className="form-actions"><button className="secondary-button" onClick={onBack}><ArrowLeft size={16}/> Wrong test? Return</button><button className="secondary-button" onClick={onSave}><ClipboardCheck size={16}/> Save Observation</button><button className="primary-button" onClick={onEvidence}>Continue to Evidence Capture <ArrowRight size={16}/></button></div></div></div><ReadingTable saved={saved}/></section>}
function ReadingTable({saved}:{saved:boolean}){const rows=[['Repeatability','50 kg','0.00','50','50.02','kg','Verified','Clear'],['Eccentricity','25 kg','0.00','25','25.01','kg','Verified','Clear'],['Indication Error','50 kg','0.00','50','50.02','kg','Pending','Needs review'],['Tare','0 kg','50.02','0','0.00','kg',saved?'Verified':'Missing',saved?'Clear':'Missing']];return <div className="readings-section"><div className="panel-heading"><div><p className="eyebrow">CAPTURED OBSERVATIONS</p><h3>Reading table</h3></div><span className="muted">{saved?'5 readings saved':'4 mock readings · 1 pending'}</span></div><div className="table-wrap"><table><thead><tr><th>Test</th><th>Load Point</th><th>Initial I</th><th>ΔL</th><th>Observed</th><th>Unit</th><th>Evidence</th><th>Quality</th><th>Timestamp</th><th>Action</th></tr></thead><tbody>{rows.map((r,i)=><tr key={r[0]}>{r.map((c,j)=><td key={j}>{j===6?<StatusBadge tone={c==='Verified'?'green':c==='Missing'?'red':'orange'}>{c}</StatusBadge>:j===7?<StatusBadge tone={c==='Clear'?'green':c==='Missing'?'red':'orange'}>{c}</StatusBadge>:c}</td>)}<td><button className="text-button">Edit</button></td></tr>)}</tbody></table></div></div>}
function Evidence({complete,onComplete,onBack}:{complete:boolean;onComplete:()=>void;onBack:()=>void}){return <section className="workflow-card wide-card"><div className="card-heading"><div><p className="eyebrow">STEP 6 OF 8 · PROOF PACKAGE</p><h2>Evidence capture</h2><p className="section-note">Link every required image or document to a test and load point before calculation.</p></div><StatusBadge tone={complete?'green':'orange'}>{complete?'Ready for Calculation':'Evidence Pending'}</StatusBadge></div><div className="evidence-grid"><UploadBox label="Scale display photo" required status="Verified"/><UploadBox label="Load point photo" required status={complete?'Verified':'Needs Retake'} onAction={onComplete}/><UploadBox label="Instrument / nameplate photo" required status="Verified"/><UploadBox label="Calibration certificate" required status="Verified"/><UploadBox label="Setup condition photo" status="Missing"/><UploadBox label="Additional notes" status="Optional"/></div><div className="quality-panel"><div><p className="eyebrow">MOCK IMAGE QUALITY CHECKER</p><h3>Evidence quality review</h3></div><div className="quality-checks"><span><Check size={14}/> Blur check</span><span><Check size={14}/> Glare check</span><span><Check size={14}/> Frame coverage</span><span><Check size={14}/> Reading visibility</span><span className="needs-retake">! Nameplate visibility</span></div></div><Validation message={!complete?'Required evidence missing or needs retake. Retake the load point photo before marking complete.':undefined}/><div className="form-actions"><button className="secondary-button" onClick={onBack}><ArrowLeft size={16}/> Back to Guided Test</button><button className="primary-button" onClick={onComplete} disabled={complete}>{complete?'Evidence verified':'Mark evidence verified'} <ArrowRight size={16}/></button></div></section>}
function Dashboard({role,cases,onCreate,onCases,onTrustGate}:{role:string;cases:WorkflowCase[];onCreate:()=>void;onCases:()=>void;onTrustGate:()=>void}){const roleCopy=role==='Lab Verifier'?['Verification queue','Setup pending','Evidence warnings','Calculation review','Retest recommended','Audit events']:role==='Officer'?['Pending approval','Manual review','Potential non-compliance','Retest requests','Reports generated','Closed cases']:role==='Admin'?['Total users','Active inspectors','Active lab verifiers','Active officers','Rule versions','Evidence thresholds','System audit events','All cases']:['My inspection cases','Draft cases','Evidence pending','Sent back by officer','Ready for TrustGate','Reports generated'];const roleValues=role==='Admin'?[String(cases.length),'—','—','—','—','—','—',String(cases.length)]:[String(cases.length),String(cases.filter(x=>x.status==='DRAFT').length),String(cases.filter(x=>x.status==='EVIDENCE_CAPTURE_IN_PROGRESS'||x.evidenceStatus==='INCOMPLETE').length),String(cases.filter(x=>x.status==='SENT_BACK_TO_INSPECTOR').length),String(cases.filter(x=>x.status==='TRUSTGATE_PASSED').length),String(cases.filter(x=>x.status==='REPORT_GENERATED').length)];return <><section className="summary-grid">{roleCopy.map((label,i)=>[label,roleValues[i]]).map(([l,v],i)=><article className={`summary-card accent-${['navy','orange','purple','blue','green','red'][i]} `} key={l}><div className="summary-value">{v}</div><div className="summary-label">{l}</div><div className="summary-delta">{i===0?'+4 this month':'Requires attention'}</div></article>)}</section><div className="content-grid"><article className="panel"><div className="panel-heading"><div><p className="eyebrow">LIVE QUEUE</p><h2>Inspection cases</h2></div><button className="text-button" onClick={onCases}>View all →</button></div><div className="table-wrap"><table><thead><tr><th>Case</th><th>Instrument</th><th>Location</th><th>Status</th></tr></thead><tbody>{cases.slice(0,6).map(x=><tr key={x.id}><td><button className="case-link" onClick={()=>window.location.href=`/cases/${encodeURIComponent(x.id)}`}>{x.id}</button></td><td>{x.instrument}</td><td>{x.location}</td><td><StatusBadge tone={x.status==='APPROVED'||x.status==='REPORT_GENERATED'?'green':x.status.includes('EVIDENCE')?'orange':'blue'}>{x.status.replaceAll('_',' ')}</StatusBadge></td></tr>)}</tbody></table></div></article><aside className="panel action-panel"><div className="panel-heading"><div><p className="eyebrow">NEXT ACTIONS</p><h2>Work queue</h2></div></div><button className="action-row" onClick={role==='Inspector'?onCreate:undefined} disabled={role!=='Inspector'} title={role==='Inspector'?'Create inspection case':'Access restricted for current role'}><span className="action-icon action-blue"><FilePlus2 size={17}/></span><span><strong>Start a new inspection</strong><small>Create case and verify instrument identity</small></span><span className="arrow">→</span></button><button className="action-row" onClick={onTrustGate}><span className="action-icon action-purple"><ShieldCheck size={17}/></span><span><strong>Resolve TrustGate checks</strong><small>4 cases require attention</small></span><span className="arrow">→</span></button></aside></div></>}
function CaseList({cases,onCreate,onView}:{cases:WorkflowCase[];onCreate:()=>void;onView:(caseId:string)=>void}){return <section className="panel cases-list"><div className="panel-heading"><div><p className="eyebrow">WORKSPACE REGISTER</p><h2>Existing inspection cases</h2></div><button className="primary-button" onClick={onCreate}><FilePlus2 size={16}/> Create case</button></div><div className="table-wrap"><table><thead><tr><th>Case ID</th><th>Instrument</th><th>District</th><th>Status</th><th>Current owner</th><th>Next action</th><th>Last updated</th><th/></tr></thead><tbody>{cases.map(x=><tr key={x.id}><td className="instrument-cell">{x.id}</td><td>{x.instrument}</td><td>{x.location}</td><td><StatusBadge tone={x.status==='APPROVED'||x.status==='REPORT_GENERATED'?'green':x.status==='NEEDS_EVIDENCE'?'orange':'blue'}>{x.status.replaceAll('_',' ')}</StatusBadge></td><td>{x.status==='REPORT_GENERATED'?'System':x.ownerRole}</td><td>{x.status==='REPORT_GENERATED'?<><span>View report</span> <button className="text-button" onClick={()=>window.location.href=`/reports/${encodeURIComponent(x.id)}`}>Open report →</button></>:x.status==='APPROVED'?'Generate report':x.status==='OFFICER_REVIEW_PENDING'?'Officer review':x.status==='SUBMITTED_TO_LAB'?'Technical review':x.status==='EVIDENCE_CAPTURE_IN_PROGRESS'?'Complete evidence':x.status==='DRAFT'||x.status==='IDENTITY_COMPLETED'?'Complete inspection':'Review case'}</td><td>{new Date(x.updatedAt).toLocaleString('en-IN')}</td><td><button className="text-button" onClick={()=>onView(x.id)}>View case →</button></td></tr>)}</tbody></table>{!cases.length&&<p className="empty-state">No saved inspection cases.</p>}</div></section>}
function ValidationHeader({eyebrow,title,description,status,tone='blue'}:{eyebrow:string;title:string;description:string;status:string;tone?:string}){return <div className="card-heading"><div><p className="eyebrow">{eyebrow}</p><h2>{title}</h2><p className="section-note">{description}</p></div><StatusBadge tone={tone}>{status}</StatusBadge></div>}
function Phase4Summary({caseData}:{caseData:CaseData}){return <div className="instrument-summary"><SummaryItem label="Case ID" value={caseData.caseId}/><SummaryItem label="Instrument type" value={caseData.instrument||'Retail weighing scale'}/><SummaryItem label="Accuracy class" value={caseData.accuracy}/><SummaryItem label="Max capacity" value={caseData.maxCapacity||'100 kg'}/><SummaryItem label="Min capacity" value={caseData.minCapacity||'20 g'}/><SummaryItem label="Verification scale interval e" value={caseData.interval||'10 g'}/><SummaryItem label="Test setup" value="Traceable"/><SummaryItem label="Evidence status" value="Verified with review"/></div>}
const calcRows=[['Repeatability','50 kg','0.00','50','50.02','0.02','0.02','0.05','Pass','Display photo'],['Eccentricity','25 kg','0.00','25','25.01','0.01','0.01','0.05','Pass','Load point photo'],['Indication Error','50 kg','0.00','50','50.08','0.08','0.08','0.05','Potential Non-Compliance','Reading record'],['Tare','0 kg','50.02','0','0.00','0.00','0.00','0.05','Pass','Tare photo']]
function CalculationEngine({caseData,run,onRun,onContinue}:{caseData:CaseData;run:boolean;onRun:()=>void;onContinue:()=>void}){return <section className="workflow-card wide-card"><ValidationHeader eyebrow="STEP 7 OF 8 · RULE-BASED VALIDATION" title="Calculation Engine" description="Computed errors are linked to captured observations and the applicable OIML limit." status={run?'Calculation complete':'Ready to calculate'} tone={run?'green':'orange'}/><Phase4Summary caseData={caseData}/><div className="summary-grid validation-summary"><article className="summary-card accent-blue"><div className="summary-value">4</div><div className="summary-label">Total readings</div></article><article className="summary-card accent-green"><div className="summary-value">{run?'4':'0'}</div><div className="summary-label">Calculations complete</div></article><article className="summary-card accent-orange"><div className="summary-value">{run?'1':'0'}</div><div className="summary-label">Review required</div></article><article className="summary-card accent-red"><div className="summary-value">{run?'1':'0'}</div><div className="summary-label">Potential non-compliance</div></article></div><div className="table-wrap calculation-table"><table><thead><tr>{['Test name','Load point','Initial Indication I','Load Increment ΔL','Observed Reading','Error E','Corrected Error Ec','MPE Limit','Result','Evidence link'].map(x=><th key={x}>{x}</th>)}</tr></thead><tbody>{calcRows.map((r,i)=><tr key={r[0]}>{r.map((c,j)=><td key={j}>{j===8?<StatusBadge tone={c==='Pass'?'green':c==='Review'?'orange':'red'}>{run?c:'Incomplete'}</StatusBadge>:c}</td>)}</tr>)}</tbody></table></div><div className="form-actions"><button className="secondary-button" onClick={onRun}>Run Calculation Check</button><button className="primary-button" onClick={onContinue} disabled={!run}>Continue to TrustGate Review <ArrowRight size={16}/></button></div></section>}
const trustChecks=[['Identity completeness','Passed','Passport and nameplate identity match.','None'],['Setup traceability','Passed','Officer, masses and environmental conditions recorded.','None'],['Evidence completeness','Warning','One load point requires a retake.','Return to Evidence Capture'],['Image quality','Warning','Nameplate visibility confidence is below threshold.','Manual review'],['Reading availability','Passed','All required observations are present.','None'],['Calculation completion','Passed','Calculation set has been generated.','None'],['Cross-observation consistency','Warning','Indication Error exceeds the mock MPE boundary.','Request retest'],['Counter-evidence readiness','Warning','Contradictory evidence must be reviewed.','Open counter-evidence'],['Officer review readiness','Warning','Decision cannot be final until warnings resolve.','Officer review']]
function TrustGateReview({evidenceComplete,calculationRun,trustgateRun,onRun,onBack,onRetest,onContinue,onSubmit}:{evidenceComplete:boolean;calculationRun:boolean;trustgateRun:boolean;onRun:()=>void;onBack:()=>void;onRetest:()=>void;onContinue:()=>void;onSubmit?:()=>void}){const ready=evidenceComplete&&calculationRun;return <section className="workflow-card wide-card"><ValidationHeader eyebrow="STEP 8 OF 8 · DECISION READINESS" title="TrustGate Review" description="A central validation layer for identity, traceability, evidence and calculation readiness." status={trustgateRun?(ready?'Ready for Decision':'Needs Evidence'):'Checks pending'} tone={trustgateRun&&ready?'green':'orange'}/><div className={`decision-card ${trustgateRun&&ready?'decision-ready':''}`}><ShieldCheck size={24}/><div><p className="eyebrow">EVIDENCE BEFORE RESULT</p><h3>{trustgateRun?(ready?'Ready for Decision':'Needs Evidence'):'Manual Review Required'}</h3><p>No final result is generated until evidence, calculation and decision-readiness checks are complete.</p></div></div><div className="trust-checks">{trustChecks.map(([name,status,reason,action])=><div className="trust-check" key={name}><strong>{name}</strong><StatusBadge tone={status==='Passed'?'green':status==='Failed'?'red':'orange'}>{status}</StatusBadge><span>{reason}</span><em>{action}</em></div>)}</div><div className="form-actions"><button className="secondary-button" onClick={onBack}><ArrowLeft size={16}/> Return to Evidence Capture</button><button className="secondary-button" onClick={onRetest}>Request Retest</button><button className="primary-button" onClick={onRun}>Run TrustGate Check</button><button className="primary-button" onClick={onSubmit||onContinue} disabled={!trustgateRun}>Submit to Lab Verifier <ArrowRight size={16}/></button></div></section>}
function CounterEvidence({recommendation,setRecommendation,onContinue}:{recommendation:string;setRecommendation:(v:string)=>void;onContinue:()=>void}){return <section className="workflow-card wide-card"><ValidationHeader eyebrow="COUNTER-EVIDENCE CHECK · FINDING VALIDATION" title="Counter-Evidence Check" description="Review supporting and contradictory evidence before marking a potential non-compliance." status="Manual review" tone="orange"/><div className="finding-card"><div><p className="eyebrow">SUSPECTED FINDING</p><h3>Indication Error exceeds MPE</h3><p>Related test: Indication Error · Load point: 50 kg</p></div><StatusBadge tone="red">Error 0.08 kg / MPE 0.05 kg</StatusBadge></div><div className="evidence-columns"><div className="evidence-review support"><h3>Supporting Evidence</h3><p>Evidence supports the suspected finding.</p><ul><li>Reading exceeds allowed limit</li><li>Photo and timestamp available</li><li>Reading record is linked to the case</li></ul><StatusBadge tone="green">3 supporting items</StatusBadge></div><div className="evidence-review contradiction"><h3>Contradictory Evidence</h3><p>Evidence that may change the decision.</p><ul><li>Other readings are within limit</li><li>Image quality issue detected</li><li>Missing load point photo; retest recommended</li></ul><StatusBadge tone="orange">3 items require review</StatusBadge></div></div><div className="evidence-record"><div className="evidence-photo">Evidence<br/>photo</div><div><p className="eyebrow">LINKED RECORD</p><strong>Reading: 50.08 kg · 26 Sep 2026 10:42</strong><p>Officer / inspector note: Display stable after load application. Confirm with retest before final finding.</p></div></div><label className="form-field recommendation-field"><span>Recommendation output</span><select value={recommendation} onChange={e=>setRecommendation(e.target.value)}><option>Confirm finding</option><option>Send for manual review</option><option>Request retest</option><option>Mark as insufficient evidence</option></select></label><div className="form-actions"><button className="secondary-button" onClick={()=>setRecommendation('Request retest')}>Request retest</button><button className="primary-button" onClick={onContinue}>Continue to Officer Review <ArrowRight size={16}/></button></div></section>}
function AuditTrail({filter,setFilter,caseId}:{filter:string;setFilter:(v:string)=>void;caseId?:string}){const filters=['All events','Evidence events','Calculation events','Officer actions','Report actions'];const [events,setEvents]=useState<Array<{id:string;caseId:string;actorRole:string;actorName:string;action:string;fromStatus?:string;toStatus?:string;createdAt?:string;timestamp?:string;remarks?:string}>>([]);const [error,setError]=useState('');useEffect(()=>{let cancelled=false;fetch(`/api/workflow/events${caseId?`?caseId=${encodeURIComponent(caseId)}`:''}`,{cache:'no-store'}).then(async response=>{if(!response.ok)throw new Error('Audit events could not be loaded from Neon.');return response.json()}).then(data=>{if(!cancelled)setEvents(data)}).catch(caught=>{if(!cancelled)setError(caught instanceof Error?caught.message:'Audit events could not be loaded.')});return()=>{cancelled=true}},[caseId]);const filtered=events.filter(event=>filter==='All events'||(filter==='Evidence events'&&event.action.toLowerCase().includes('evidence'))||(filter==='Calculation events'&&/(calculat|reading|test setup|trustgate|test)/i.test(event.action))||(filter==='Officer actions'&&event.actorRole==='Officer')||(filter==='Report actions'&&event.action.toLowerCase().includes('report')));return <section className="panel audit-panel"><div className="panel-heading"><div><p className="eyebrow">NEON · WORKFLOW_EVENTS</p><h2>Complete audit trail</h2><p className="section-note">Immutable workflow transitions loaded from Neon PostgreSQL.</p></div><StatusBadge tone="blue">{filtered.length} recorded events</StatusBadge></div><div className="audit-filters">{filters.map(f=><button className={filter===f?'active':''} key={f} onClick={()=>setFilter(f)}>{f}</button>)}</div>{error?<div className="validation" role="alert">{error}</div>:<div className="report-timeline audit-timeline">{filtered.map(event=><div className="report-event" key={event.id}><span className="timeline-dot"/><div><strong>{event.action}</strong><span>Case {event.caseId} · {event.actorRole} · {event.actorName}</span><p>{event.fromStatus||'—'} → {event.toStatus||'Recorded'} · {(() => { const raw = event.timestamp || event.createdAt; if (!raw) return 'Not recorded'; const parsed = new Date(raw); return Number.isNaN(parsed.getTime()) ? 'Not recorded' : parsed.toLocaleString('en-IN') })()}</p>{event.remarks&&<small>{event.remarks}</small>}</div></div>)}</div>}{!error&&!filtered.length&&<p className="empty-state">No Neon workflow events match this filter.</p>}</section>}
export default TrustGateDashboard
